<?php
require_once __DIR__.'/includes/bootstrap.php';require_login();admin_only();verify_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$pass=$_POST['password']??'';$role=($_POST['role']??'staff')==='admin'?'admin':'staff';if($name&&filter_var($email,FILTER_VALIDATE_EMAIL)&&strlen($pass)>=10){try{$st=$pdo->prepare("INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,?)");$st->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT),$role]);flash('Staff account created.');}catch(PDOException $e){flash('Could not create account. Email may already exist.','error');}}else flash('Fill all fields and use a password with at least 10 characters.','error');redirect('staff.php');}
$rows=$pdo->query("SELECT id,name,email,role,active,created_at FROM users ORDER BY id")->fetchAll();layout_start('Staff accounts','staff');?>
<section class="panel form-panel"><h3>Create staff account</h3><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><label>Full name<input name="name" required></label><label>Email<input name="email" type="email" required></label><label>Password (10+ characters)<input name="password" type="password" minlength="10" required></label><label>Role<select name="role"><option value="staff">Staff</option><option value="admin">Admin</option></select></label><div class="form-actions"><button class="btn primary">Create account</button></div></form></section><section class="panel table-panel"><div class="panel-head"><div><h3>Team members</h3><p class="muted">Administrator and staff access</p></div></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Created</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=h($r['name'])?></b></td><td><?=h($r['email'])?></td><td><span class="badge soft"><?=h($r['role'])?></span></td><td><span class="badge success"><?=$r['active']?'Active':'Disabled'?></span></td><td><?=date('d M Y',strtotime($r['created_at']))?></td></tr><?php endforeach;?></tbody></table></div></section><?php layout_end();?>
